export const getStudySheet = (id) => STUDY_SHEETS.find((sheet) => sheet.id === id);
export const getSheetForQuestion = (questionId) => STUDY_SHEETS.find((sheet) => sheet.questionIds.includes(questionId));
export const getSheetQuestions = (sheet, questions) => sheet.questionIds.map((id) => questions.find((question) => question.id === id)).filter(Boolean);

